import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

public class Main {

    // 计算单组测试数据的答案
    public static int solveCase(int n, int m, String[] grid) {
        // 统计初始总差值：B 记为 +1，S 记为 -1
        int totalDiff = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i].charAt(j) == 'B') {
                    totalDiff++;
                } else {
                    totalDiff--;
                }
            }
        }

        // 最大可能差值绝对值不超过总货位数
        int maxDiff = n * m;
        int offset = maxDiff;
        int size = 2 * maxDiff + 1;
        int inf = 1 << 29;

        // dp[i] 表示当前处理到某些排后，移除部分差值为 i - offset 时的最小移除总数
        int[] dp = new int[size];
        Arrays.fill(dp, inf);
        dp[offset] = 0;

        // 逐排进行分组背包
        for (int i = 0; i < n; i++) {
            // 记录当前排中某个差值对应的最小移除数量
            Map<Integer, Integer> best = new HashMap<>();

            // 移除长度为 0 的前缀
            int curDiff = 0;
            best.put(0, 0);

            // 枚举所有前缀
            for (int j = 0; j < m; j++) {
                if (grid[i].charAt(j) == 'B') {
                    curDiff++;
                } else {
                    curDiff--;
                }

                int len = j + 1;

                // 相同差值只保留最小移除数量
                if (!best.containsKey(curDiff) || len < best.get(curDiff)) {
                    best.put(curDiff, len);
                }
            }

            int[] ndp = new int[size];
            Arrays.fill(ndp, inf);

            // 枚举旧状态
            for (int oldIdx = 0; oldIdx < size; oldIdx++) {
                if (dp[oldIdx] == inf) {
                    continue;
                }

                // 枚举当前排可选方案
                for (Map.Entry<Integer, Integer> entry : best.entrySet()) {
                    int delta = entry.getKey();
                    int cost = entry.getValue();
                    int newIdx = oldIdx + delta;

                    if (newIdx >= 0 && newIdx < size) {
                        ndp[newIdx] = Math.min(ndp[newIdx], dp[oldIdx] + cost);
                    }
                }
            }

            dp = ndp;
        }

        // 目标：移除部分差值恰好等于 totalDiff
        return dp[offset + totalDiff];
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder sb = new StringBuilder();

        int t = fs.nextInt();
        for (int caseId = 0; caseId < t; caseId++) {
            int n = fs.nextInt();
            int m = fs.nextInt();

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = fs.next();
            }

            sb.append(solveCase(n, m, grid)).append('\n');
        }

        System.out.print(sb.toString());
    }
}

